theorem GoodOn.union {s t : Finset ℤ} {bs cs : Finset (Finset ℤ)}
    (hs : GoodOn s bs) (ht : GoodOn t cs) (hst : Disjoint s t) :
    GoodOn (s ∪ t) (bs ∪ cs)

theorem goodBlock_triple {x y z : ℤ} (hxy : x ≠ y) (hxz : x ≠ z)
    (hyz : y ≠ z) {k : ℕ} (hs : x + y + z = (3 : ℤ)^k) :
    GoodBlock {x, y, z}

lemma GoodOn.block_sum_bounds {r : ℕ} {bs : Finset (Finset ℤ)}
    (hs : GoodOn (interval r) bs) {b : Finset ℤ} (hb : b ∈ bs) :
    0 < b.sum id ∧ b.sum id ≤ 3*(r:ℤ)

lemma GoodOn.contract {s : Finset ℤ} {bs : Finset (Finset ℤ)}
    (hs : GoodOn s bs) {b : Finset ℤ} (hb : b ∈ bs) {a r : ℤ}
    (ha : a ∈ b) (hr : r ∈ b) (har : a ≠ r) (hd : a+r ∉ s) :
    GoodOn (contractSupport s a r) (insert (contractBlock b a r) (bs.erase b))

lemma GoodOn.erase {s : Finset ℤ} {bs : Finset (Finset ℤ)}
    (hs : GoodOn s bs) {b : Finset ℤ} (hb : b ∈ bs) :
    GoodOn (s \ b) (bs.erase b)

lemma GoodOn.maximum_partner {r : ℕ} {bs : Finset (Finset ℤ)}
    (hs : GoodOn (interval r) bs) (hr : 2 ≤ r) (hmod : r % 3 = 2) :
    ∃ b ∈ bs, (r:ℤ) ∈ b ∧ ∃ a ∈ b, a ≠ (r:ℤ) ∧ ¬ (3:ℤ) ∣ a

theorem ZeroPartition.union {s t : Finset ℤ} {bs cs : Finset (Finset ℤ)}
    (hs : ZeroPartition s bs) (ht : ZeroPartition t cs) (hst : Disjoint s t) :
    ZeroPartition (s ∪ t) (bs ∪ cs)

theorem residueTriple_disjoint {k j : ℤ} {σ : ℤ → ℤ}
    (hσ : DisplacementPermutation k j σ) {u v : ℤ}
    (hu : u ∈ displacementDomain k j) (hv : v ∈ displacementDomain k j)
    (huv : u ≠ v) : Disjoint (residueTriple σ u) (residueTriple σ v)

theorem zeroPartition_single_triple {x y z : ℤ}
    (hxy : x ≠ y) (hxz : x ≠ z) (hyz : y ≠ z) (hs : x+y+z = 0) :
    ZeroPartition {x,y,z} {{x,y,z}}

theorem hasGood_complement_interval {k : ℕ} {h lo : ℤ}
    (hp : (3 : ℤ)^k = 2 * h + 1) (hlo : lo ≤ h + 1) :
    HasGood (Finset.Icc lo (2 * h + 1 - lo))

theorem hasGood_symmetric_interval {P r : ℤ} {k : ℕ}
    (hp : P = (3 : ℤ)^k) (hr : 0 ≤ r) (hmod : r % 3 = 0 ∨ r % 3 = 1) :
    HasGood (Finset.Icc (P - r) (P + r))

theorem LangfordPairing.reflect {d k h : ℤ} {ps : Finset (ℤ × ℤ)}
    (hp : LangfordPairing d k h ps) :
    LangfordPairing d k (2*(k-d+1)+2-h) (reflectPairs (2*(k-d+1)+1) ps)

theorem LangfordPairing.with_doubling_centered {d k h : ℤ} {ps : Finset (ℤ × ℤ)}
    (hl : LangfordPairing d k h ps) :
    ∃ σ : ℤ → ℤ, DisplacementPermutation k (h+2*(d-1)-k-1) σ

theorem contractBlock_eq_collision_pair {r : ℕ} {P a : ℤ} {t : ℕ}
    {bs : Finset (Finset ℤ)} {b : Finset ℤ}
    (hs : GoodOn (interval r) bs) (hb : b ∈ bs)
    (ha : a ∈ b) (hr : (r : ℤ) ∈ b) (har : a ≠ (r : ℤ))
    (hP : P = (3 : ℤ)^t) (hPr : 2*(r : ℤ) < P)
    (hc : P-((r : ℤ)+a) ∈ criticalSupport (r : ℤ) a) :
    contractBlock b a (r : ℤ) = {(r : ℤ)+a, P-((r : ℤ)+a)}

theorem contractBlock_sum {b : Finset ℤ} {a r : ℤ}
    (ha : a ∈ b) (hr : r ∈ b) (har : a ≠ r) (hd : a+r ∉ b) :
    (contractBlock b a r).sum id = b.sum id

theorem eq_pair_of_card_le_two_of_sum {b : Finset ℤ} {d P : ℤ}
    (hd : d ∈ b) (hcard : b.card ≤ 2) (hsum : b.sum id = P) (hne : d ≠ P) :
    b = {d, P-d}

theorem toBlocksZ_ne_of_differZ {support : List ℤ} {bs cs : List (List ℤ)}
    (hb : framesOK support bs = true) (hc : framesOK support cs = true)
    (h : differZ bs cs = true) : toBlocksZ bs ≠ toBlocksZ cs

theorem three_le_count_add_of_source {P r t : ℕ} {a : ℤ} {bs : Finset (Finset ℤ)} {b : Finset ℤ}
    (hP : P = 3 ^ t) (hPr : 2 * r < P) (hs : GoodOn (interval r) bs) (hb : b ∈ bs) (ha : a ∈ b)
    (hr : (r : ℤ) ∈ b) (har : a ≠ (r : ℤ)) (hF : ThreeFrames (r : ℤ) a) : 3 ≤ count (P + r)
